// DE INHOUD VAN EEN VOORWAARDE — de laag die iedereen deelt.
//
// Waarom dit bestand bestaat. `invulling.tsx` heeft `VoorwaardeInhoud` nodig (de
// gedeelde ingang: een voorwaarde leest overal hetzelfde) en `voorwaarden.tsx`
// heeft `InvullingKnop` nodig (het ⚙ op elke voorwaarde-rij). Zolang die twee
// componenten in diezelfde twee bestanden stonden, was dat een IMPORTLUS. Die
// lus draagt alleen zolang geen van beide modules de ander op MODULENIVEAU
// aanroept; Vite maakt van een import een runtime-opzoeking, dus de
// hoisting-garantie van kaal ESM geldt daar niet (mutatie MUT-1 van de
// dt2-eindreview: één module-niveau-aanroep en een heel testbestand valt om met
// `TypeError: VoorwaardeInhoud is not a function`).
//
// De ontkoppeling gaat de kant op die WERKT. `InvullingKnop` naar een derde
// module verplaatsen kan niet — hij leunt op `dekkingsStand`, `invullingIndex()`
// en `openInvulling`, het hart van de paneelmachinerie. De INHOUDSLAAG kan wel:
// zij leest alleen het model en de taal, en kent het paneel niet. Zij staat dus
// hier, en `voorwaarden.tsx` en `invulling.tsx` wijzen er allebei alleen nog
// naartoe. De rij eromheen (met haar twee uitgangen ⌕ en ⚙) blijft in
// `voorwaarden.tsx`: dát is de laag die het paneel wél kent.
//
// Gedragsbron ongewijzigd: constraintChips, chipSlots, missingChip,
// constraintNode en condContent in de bevroren `viewer-bevroren/assets/doc.js`; de zin-
// en slotstructuur komt uit `constraintSentence` in de modellaag (parse.js) en
// wordt hier NIET herbouwd.
import { For, Show, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { curie } from '../../model-grens.js';
import { tekst } from '../../stores/weergave.js';
import './voorwaarden.css';

/** Eén slot van een voorwaarde: het woord, en de definitie van de term
 *  erachter (leeg als de data die niet geeft). */
export interface Slot { text: string; desc?: string }

/** Een voorwaarde zoals `constraintSentence` haar oplevert. De velden die de
 *  LEESWEERGAVE gebruikt; de dekkings- en bewerkvelden blijven buiten dit type
 *  tot hun eigen taak ze nodig heeft. Het type staat hier en niet in
 *  `model-grens.ts` om dezelfde reden als de kaarttypen: dat is een gedeeld
 *  bestand waar parallelle lanes ook in schrijven. */
export interface Voorwaarde {
  /** Het adres van de RIJ. Een conformsToPolicy-voorwaarde is een blanke knoop
   *  en heeft dus geen eigen IRI; parse.js geeft haar een samengestelde
   *  `rowRef` (r.3980), en dát is waarop het invulling-paneel haar aanwijst. */
  rowRef?: string | null;
  iri?: string | null;
  label?: string | null;
  comment?: string | null;
  sentence?: string;
  logical?: string | null;
  children?: Voorwaarde[];
  slots?: {
    left: Slot | null;
    operator: Slot | null;
    /** `descs` en `iris` lopen in de PAS met `texts` (parse.js): per waarde-chip
     *  haar uitleg en, als de waarde een knoop is, haar IRI. */
    right: { texts: string[]; descs?: string[]; iris?: (string | null)[] } | null;
  } | null;
  left?: string | null;
  operator?: string | null;
  right?: string[];
  rightOperandReference?: string[];
  unaryOperator?: boolean;
  unknownProps?: { curie: string; values: string[] }[];
  technicalMeasure?: boolean;
  conformsOp?: boolean;
  conformsTo?: string | null;
  organisational?: boolean;
  /** Door de WEERGAVE samengestelde rij: de doelbinding (verbetering 5). */
  doelbinding?: boolean;
}

/** Hoeveel waarde-chips er staan voordat de rest achter de knop verdwijnt.
 *  Letterlijk de RIGHT_CHIP_SHOWN van de bevroren viewer. */
export const RECHTER_CHIPS_GETOOND = 5;

/** Boven dit aantal bladen start een en/of-groep ingeklapt (GROUP_COLLAPSE_
 *  LEAVES): een boom die de halve kaart vult, vertelt niets meer. */
export const GROEP_INKLAP_BLADEN = 10;

const LOGISCHE_OPERATOREN = ['and', 'andSequence', 'or', 'xone'];

/** Het woord boven een logische groep ("alle van", "één van"). Een operator
 *  die de kern niet kent houdt zijn eigen naam. */
export function logischeKop(op: string): string {
  return LOGISCHE_OPERATOREN.includes(op) ? tekst('logicalHead.' + op) : op;
}

/** Het aantal BLADEN onder een voorwaarde: een groep telt haar kinderen, een
 *  blad telt als één. */
export function telBladen(c: Voorwaarde): number {
  if (!c.children || !c.children.length) return 1;
  return c.children.reduce((n, ch) => n + telBladen(ch), 0);
}

/** De slots waarop de chips gebouwd worden. Kwam de zinbouwer niet tot slots
 *  (een samengestelde voorwaarde waarvan de leden niet uitgelezen konden
 *  worden), dan worden ze hier alsnog uit de RAUWE velden gemaakt. */
export function chipSlots(c: Voorwaarde): NonNullable<Voorwaarde['slots']> {
  if (c.slots) return c.slots;
  const rechts = [...(c.right || []), ...(c.rightOperandReference || [])];
  return {
    left: c.left ? { text: c.left } : null,
    operator: c.operator ? { text: c.operator } : null,
    right: rechts.length ? { texts: rechts } : null,
  };
}

/** De uitleg bij een ontbrekend slot: welk predicaat ontbreekt, en wat er dan
 *  wél op de knoop staat (missingSlotTitle in de bevroren viewer). */
function ontbreektTitel(pred: string, unknownProps?: { curie: string; values: string[] }[]): string {
  let txt = tekst('slot.missingTitle', { pred });
  if (unknownProps && unknownProps.length) {
    txt += tekst('slot.unknownProps')
      + unknownProps.map((u) => `${u.curie} → ${u.values.join(', ')}`).join('; ') + '.';
  }
  return txt;
}

/** Waarschuwings-chip voor een ontbrekend slot. Draagt `unknownProps` een
 *  kandidaat (een eigenschap die we niet herkenden), dan toont de chip diens
 *  curie in plaats van alleen "ontbreekt" — de lezer ziet dan wát er staat. */
function OntbreektChip(props: {
  sleutel: string; pred: string; unknownProps?: { curie: string; values: string[] }[];
}): JSX.Element {
  const kandidaat = () => (props.unknownProps || []).find((u) => u && u.curie);
  return (
    <span class="c-slot missing" title={ontbreektTitel(props.pred, props.unknownProps)}>
      <span class="c-warn" aria-hidden="true">
        <svg viewBox="0 0 16 16" width="11" height="11">
          <path d="M8 1.5 15 14H1z" fill="#e3b341" stroke="#a97a10" stroke-width="1" />
          <rect x="7.3" y="6" width="1.4" height="4" rx=".7" fill="#5c4304" />
          <circle cx="8" cy="11.8" r=".9" fill="#5c4304" />
        </svg>
      </span>
      <span>{kandidaat() ? kandidaat()!.curie : tekst(props.sleutel)}</span>
    </span>
  );
}

export function Chip(props: {
  klasse: string; tekst: string; desc?: string;
  /** DE CHEVRON OP DE CHIP (eigenaarsverzoek 15 sep 2026). Draagt deze waarde
   *  een formulier-shape, dan is de chip de KOP van de uitklap eronder, en dan
   *  hoort het driehoekje erop te staan in plaats van ergens aan het einde van
   *  de rij. De chip blijft op zijn plek staan; alleen zijn binnenkant wordt een
   *  flexregel met het driehoekje erachter (`.c-slot.vouwkop` in
   *  voorwaarden.css). */
  chevron?: JSX.Element | null;
}): JSX.Element {
  return (
    <span
      class={'c-slot ' + props.klasse + (props.chevron ? ' vouwkop' : '')}
      data-desc={props.desc || undefined}
    >
      {/* DE TEKST KRIJGT ALLEEN EEN WIKKEL ALS ER EEN CHEVRON NAAST STAAT, en
          dat is geen zuinigheid maar een grens. Een vouwkop-chip is een
          `inline-flex`, en in een flexcontainer werkt `text-overflow` niet op
          de anonieme tekstknoop — de wikkel geeft de tekst een eigen doos die
          kan krimpen en afkappen, zodat het driehoekje blijft staan
          (`.c-slot.vouwkop > .c-slot-tekst` in voorwaarden.css, hetzelfde
          idioom als het ✎ in een kaarttitel). Een GEWONE chip is een
          `inline-block` en draagt zijn elisie zelf; daar zou de wikkel een lege
          extra knoop zijn in een reeks die per kaart in de honderden loopt. */}
      <Show when={props.chevron} fallback={props.tekst}>
        <span class="c-slot-tekst">{props.tekst}</span>
      </Show>
      {props.chevron}
    </span>
  );
}

/** DE SPATIE TUSSEN TWEE CHIPS — een ECHTE tekstknoop (eigenaarsbesluit 8 sep
 *  2026: "kopieerbare voorwaarden").
 *
 *  Het probleem dat zij oplost. Een chip-reeks stond als drie `<span>`en
 *  rúg-aan-rug in de DOM, met een `gap` van 4px ertussen. Een CSS-gap is
 *  vormgeving en geen inhoud: hij komt niet mee in `textContent` en niet in het
 *  klembord. Wie een voorwaarde-rij selecteerde en plakte kreeg dus
 *  "doelis gelijk aanRegistratie van laadpalen" — een zin die niemand kan lezen
 *  en die als citaat in een verslag of ticket onbruikbaar is.
 *
 *  DE RUIMTE VERVANGT DE GAP, hij komt er niet bij. `.c-chips` zet daarom
 *  `column-gap: 0` (de rij-gap blijft, voor omgebroken regels) en deze span
 *  draagt precies dezelfde 4px als flex-basis. Zo verandert er geen pixel aan de
 *  weergave; wat verandert is dat de spatie nu ook in de tekst staat.
 *
 *  Waarom een `<span>` en niet een kaal `{' '}`: whitespace-only tekst TUSSEN
 *  flex-items levert geen anoniem flex-item op (CSS Flexbox §4) — de browser
 *  laat hem weg, en wat niet gerenderd wordt is bij een selectie niet
 *  betrouwbaar mee te kopiëren. Een span is een echt flex-item met een echte
 *  spatie erin. */
export function ChipRuimte(): JSX.Element {
  return <span class="c-ruimte"> </span>;
}

/** De slot-chips van één voorwaarde: [grootheid][operator][waarde]. Dezelfde
 *  vorm overal — in de Voorwaarden van een regel én in de afbakening van een
 *  collectie.
 *
 *  VERBETERING 3 (besluit 4 sep). ELKE LIJSTWAARDE EEN EIGEN CHIP was al de
 *  vorm; wat erbij komt is de UITGANG. De bevroren viewer kortte een lange
 *  rdf:List in tot vijf chips plus een gedempte "… (14 waarden)"-chip, en zette
 *  de volledige lijst als `title` op elke chip: alleen met een muis, alleen als
 *  hover, en als één komma-string die niet meer als opsomming leest. Hier is
 *  het een KNOP: hij zegt hoeveel er zijn, klapt de overige chips in dezelfde
 *  vorm uit, en klapt weer in. */
/** WELKE WAARDE-CHIP VAN DEZE RIJ DE UITKLAP DRAAGT, of `null`.
 *
 *  `dekt` is de dekkingsvraag van de aanroeper (`dektKnoop`); deze module kent
 *  de graaf niet en houdt dat zo — zij is de INHOUDSLAAG (zie de kop van dit
 *  bestand).
 *
 *  TWEE GRENZEN, en elk kost iets als je hem laat vallen:
 *
 *   1. DE EERSTE GEDEKTE WAARDE WINT, en er is er één per rij. Het lijf klapt
 *      onder de HELE rij open; twee vouwen op één rij zouden om datzelfde lijf
 *      vechten, en de lezer zou aan de chevron niet zien welke van de twee hij
 *      opende.
 *   2. ALLEEN EEN CHIP DIE ER OOK STAAT. Boven `RECHTER_CHIPS_GETOOND` waarden
 *      verdwijnen de overige achter de "toon alle n"-knop; een chevron op een
 *      chip die pas na een tweede klik verschijnt, is een vouwkop die je niet
 *      kunt zien. Een rdf:List van veertien gemeentecodes is bovendien geen
 *      kandidaat voor "dit is de knoop achter deze rij". */
export function vouwWaarde(
  c: Voorwaarde, dekt: (iri: string) => boolean,
): string | null {
  const iris = chipSlots(c).right?.iris || [];
  for (let i = 0; i < iris.length && i < RECHTER_CHIPS_GETOOND; i += 1) {
    const iri = iris[i];
    if (iri && dekt(iri)) return iri;
  }
  return null;
}

export function ConstraintChips(props: {
  c: Voorwaarde;
  /** De waarde die de uitklap draagt (zie `vouwWaarde`), en de chevron die op
   *  haar chip hoort. De chevron wordt op precies één chip gezet. */
  vouwIri?: string | null;
  chevron?: JSX.Element | null;
}): JSX.Element {
  const [alles, setAlles] = createSignal(false);
  const slots = createMemo(() => chipSlots(props.c));
  const teksten = () => slots().right?.texts || [];
  const descs = () => slots().right?.descs || [];
  const iris = () => slots().right?.iris || [];
  // OP DE INDEX EN NIET OP DE IRI. Dezelfde knoop mag twee keer in één
  // rechterlijst staan; een vergelijking op IRI zou de chevron-node dan twee
  // keer monteren, en dat is in Solid dezelfde node op twee plekken.
  const vouwIndex = () => (props.vouwIri ? iris().indexOf(props.vouwIri) : -1);
  const lang = () => teksten().length > RECHTER_CHIPS_GETOOND + 1;
  const getoond = () => (lang() && !alles()
    ? teksten().slice(0, RECHTER_CHIPS_GETOOND) : teksten());
  return (
    <span class="c-chips">
      <Show
        when={slots().left}
        fallback={(
          <OntbreektChip
            sleutel="slot.leftMissing" pred="odrl:leftOperand"
            unknownProps={props.c.unknownProps}
          />
        )}
      >{(s) => <Chip klasse="left" tekst={s().text} desc={s().desc} />}</Show>
      <ChipRuimte />
      <Show
        when={slots().operator}
        fallback={(
          <OntbreektChip
            sleutel="slot.operatorMissing" pred="odrl:operator"
            unknownProps={props.c.unknownProps}
          />
        )}
      >{(s) => <Chip klasse="op" tekst={s().text} desc={s().desc} />}</Show>
      <ChipRuimte />
      <Show
        when={slots().right}
        fallback={(
          <Show when={!props.c.unaryOperator}>
            <OntbreektChip
              sleutel="slot.valueMissing" pred="odrl:rightOperand"
              unknownProps={props.c.unknownProps}
            />
          </Show>
        )}
      >
        <For each={getoond()}>{(t, i) => (
          <>
            {/* Tussen de waarde-chips onderling net zo goed: een rdf:List van
                veertien gemeentecodes hoort als "a b c" te plakken, niet als
                "abc". De eerste waarde-chip krijgt hem NIET — de ruimte na de
                operator staat er al. */}
            <Show when={i() > 0}><ChipRuimte /></Show>
            <Chip
              klasse="right" tekst={t} desc={descs()[i()]}
              chevron={i() === vouwIndex() ? props.chevron : null}
            />
          </>
        )}</For>
        <Show when={lang()}>
          <ChipRuimte />
          <button
            type="button" class="c-slot more c-meer"
            aria-expanded={alles() ? 'true' : 'false'}
            onClick={() => setAlles((v) => !v)}
          >
            {alles() ? tekst('constraint.showFewer')
              : tekst('constraint.showAll', { n: teksten().length })}
          </button>
        </Show>
      </Show>
    </span>
  );
}

/** De naam van een benoemde voorwaarde: CONTEXT, geen inhoud. Hij staat als
 *  klein gedempt bijschrift RECHTS van de chips (feedback aug 2026: vóór de
 *  chips lijnden benoemde en blanke rijen niet meer uit). */
export function Noot(props: { c: Voorwaarde }): JSX.Element {
  return (
    <Show when={props.c.label}>{(l) => (
      <>
        {/* Vóór de noot óók een ruimte: zij staat naast de chips van de rij,
            en die plakten eraan vast ("…is opgegeven \"true\"Traceparent is
            opgegeven"). */}
        <ChipRuimte />
        <span class="c-note muted">{l()}</span>
        {/* FAMILIE 2 van de kopieerveeg (9 sep 2026): achter de noot staat het ⌕
            van de rij, gescheiden door de `gap: 10px` van `.constraint`. Geplakt
            las dat als "Alleen eigen gemeente⌕". De ruimte hoort BINNEN deze
            `Show`: zonder noot valt zij weg en scheidt zij niets. */}
        <ChipRuimte />
      </>
    )}</Show>
  );
}

/** De hover van een rij: naam en toelichting van de voorwaarde. */
export function titelVan(c: Voorwaarde): string | undefined {
  return [c.label, c.comment].filter(Boolean).join(' — ') || undefined;
}

/** De INHOUD van een voorwaarde, los van de rij eromheen: een blad toont zijn
 *  chips, een logische groep haar leden.
 *
 *  VERBETERING 2 (besluit 4 sep). De bevroren viewer tekende de groep al met
 *  een kop en een ingesprongen lijst, maar die kop was niet meer dan een
 *  operator-chip: voor een schermlezer een losse span tussen de rijen, zonder
 *  naam en zonder grens. Hier is de groep een ECHTE groep — `role="group"` met
 *  de samenvatting als toegankelijke naam — draagt haar kop het AANTAL leden
 *  (zodat "alle van" niet hoeft te worden nageteld), en stempelt elk niveau
 *  zijn `data-diepte`, waar de inspringing en de kleur van de kantlijn op
 *  meeschalen. */
export function ConstraintKnoop(props: { c: Voorwaarde; diepte?: number }): JSX.Element {
  const diepte = () => props.diepte || 0;
  const groep = () => !!(props.c.logical && props.c.children && props.c.children.length);
  const naam = () => tekst('constraint.foldSummary', {
    label: props.c.label || tekst('constraint.compound'),
    head: logischeKop(props.c.logical as string),
    n: telBladen(props.c),
  });
  return (
    <Show
      when={groep()}
      fallback={(
        <span class="c-leaf" title={titelVan(props.c)}>
          <ConstraintChips c={props.c} />
          <Noot c={props.c} />
        </span>
      )}
    >
      <div
        class="c-group" role="group" aria-label={naam()}
        data-diepte={String(diepte())} title={titelVan(props.c)}
      >
        <div class="c-group-head">
          <span class="c-slot op">{logischeKop(props.c.logical as string)}</span>
          <span class="c-group-telling muted">
            {tekst('constraint.groupCount', { n: telBladen(props.c) })}
          </span>
          <Noot c={props.c} />
        </div>
        <ul class="clean c-group-items" data-diepte={String(diepte() + 1)}>
          <For each={props.c.children}>{(ch) => (
            <li class="c-group-item"><ConstraintKnoop c={ch} diepte={diepte() + 1} /></li>
          )}</For>
        </ul>
      </div>
    </Show>
  );
}

/** DE INHOUD VAN ÉÉN VOORWAARDE, los van de rij eromheen — `condContent`
 *  (doc.js r.4033), woord voor woord: een logische groep leest als geneste
 *  rijen, een voorwaarde mét slots als chips, en wat geen van beide is als haar
 *  zin.
 *
 *  DIT IS DE GEDEELDE INGANG. De bevroren viewer schrijft er zelf bij waarom:
 *  "Gedeeld door de voorwaardenlijst van een regel, het blok 'Niet afgedwongen'
 *  en de rijen in het invulling-paneel — een voorwaarde leest overal
 *  hetzelfde." In deze tak was dat een tijdlang niet zo: `invulling.tsx` droeg
 *  een eigen kopie zonder truncatie, zonder de uitleg per slot en zonder de
 *  ontbrekend-slot-chip (eindreview deeltraject 2, IMP-2). Vandaar één functie
 *  met drie takken, en drie aanroepers.
 *
 *  Het LABEL gaat er in de groepstak uit (`{ ...c, label: null }`), precies als
 *  in de bevroren viewer: de aanroeper zet het als `.c-note` naast de inhoud, en
 *  anders staat het er tweemaal. */
export function VoorwaardeInhoud(props: { c: Voorwaarde }): JSX.Element {
  const groep = () => !!(props.c.logical && props.c.children && props.c.children.length);
  return (
    <Show
      when={groep()}
      fallback={(
        <Show
          when={props.c.slots}
          fallback={<span class="sentence">{props.c.sentence || curie(props.c.iri || '')}</span>}
        >
          <ConstraintChips c={props.c} />
        </Show>
      )}
    >
      <ConstraintKnoop c={{ ...props.c, label: null }} />
    </Show>
  );
}
